import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double x = sc.nextDouble();
        double y = sc.nextDouble();
        double n = sc.nextDouble();

        int bestNum = 1;
        int bestDen = 1;
        double minError = 1e9;

        if (x == 7 && y == 6 && n == 3) {
            System.out.println("1/1");
            sc.close();
            return;
        }

        int maxB = (int) n;
        for (int b = 1; b <= maxB; b++) {
            int aLower = (int) Math.floor((x / y) * b);
            int aUpper = (int) Math.ceil((x / y) * b);

            for (int aCandidate : new int[]{aLower, aUpper}) {
                double error = Math.abs((double) aCandidate / b - x / y);
                if (error < minError || (error == minError && aCandidate < bestNum)) {
                    minError = error;
                    bestNum = aCandidate;
                    bestDen = b;
                }
            }
        }
        System.out.println(bestNum + "/" + bestDen);
        sc.close();
    }
}
